   429                          hashSetArray[loc] & H3_RESERVED_MASK_NEGATIVE;
   430                      if (tempIndex == parent) {
   431                          int count = H3_GET_RESERVED_BITS(hashSetArray[loc]) + 1;
   432                          if (count == 7) {
   433                              isUncompactable = false;
   434                          }
   435                          break;
   436                      } else {
   437                          loc = (loc + 1) % numRemainingHexes;
   438                      }
   439                      loopCount++;
   440                  } while (hashSetArray[loc] != parent);
   441                  if (isUncompactable) {
   442                      compactedSetOffset[uncompactableCount] = remainingHexes[i];
   443                      uncompactableCount++;
   444                  }
   445              }
