   448          memset(hashSetArray, 0, numHexes * sizeof(H3Index));
   449          compactedSetOffset += uncompactableCount;
   450          memcpy(remainingHexes, compactableHexes,
   451                 compactableCount * sizeof(H3Index));
   452          numRemainingHexes = compactableCount;
   453          H3_MEMORY(free)(compactableHexes);
   454      }
   455      H3_MEMORY(free)(remainingHexes);
   456      H3_MEMORY(free)(hashSetArray);
   457      return E_SUCCESS;
