   460  /**
   461   * uncompactCells takes a compressed set of cells and expands back to the
   462   * original set of cells.
   463   *
   464   * Skips elements that are H3_NULL (i.e., 0).
   465   *
   466   * @param   compactSet  Set of compacted cells
   467   * @param   numCompact  The number of cells in the input compacted set
   468   * @param   outSet      Output array for decompressed cells (preallocated)
   469   * @param   numOut      The size of the output array to bound check against
   470   * @param   res         The H3 resolution to decompress to
   471   * @return              An error code if output array is too small or any cell
   472   *                      is smaller than the output resolution.
   473   */
   474  H3Error H3_EXPORT(uncompactCells)(const H3Index *compactedSet,
   475                                    const int64_t numCompacted, H3Index *outSet,
   476                                    const int64_t numOut, const int res) {
   477      int64_t i = 0;
   478
   479      for (int64_t j = 0; j < numCompacted; j++) {
   480          if (!_hasChildAtRes(compactedSet[j], res)) return E_RES_MISMATCH;
   481
   482          for (IterCellsChildren iter = iterInitParent(compactedSet[j], res);
   483               iter.h; i++, iterStepChild(&iter)) {
   484              if (i >= numOut) return E_MEMORY_BOUNDS;  // went too far; abort!
   485              outSet[i] = iter.h;
   486          }
   487      }
   488      return E_SUCCESS;
   489  }
