   526  /**
   527   * isPentagon takes an H3Index and determines if it is actually a pentagon.
   528   * @param h The H3Index to check.
   529   * @return Returns 1 if it is a pentagon, otherwise 0.
   530   */
   531  int H3_EXPORT(isPentagon)(H3Index h) {
   532      return _isBaseCellPentagon(H3_GET_BASE_CELL(h)) &&
   533             !_h3LeadingNonZeroDigit(h);
   534  }
