   536  /**
   537   * Returns the highest resolution non-zero digit in an H3Index.
   538   * @param h The H3Index.
   539   * @return The highest resolution non-zero digit in the H3Index.
   540   */
   541  Direction _h3LeadingNonZeroDigit(H3Index h) {
   542      for (int r = 1; r <= H3_GET_RESOLUTION(h); r++)
   543          if (H3_GET_INDEX_DIGIT(h, r)) return H3_GET_INDEX_DIGIT(h, r);
   544
   545      // if we're here it's all 0's
   546      return CENTER_DIGIT;
   547  }
