   549  /**
   550   * Rotate an H3Index 60 degrees counter-clockwise about a pentagonal center.
   551   * @param h The H3Index.
   552   */
   553  H3Index _h3RotatePent60ccw(H3Index h) {
   554      // rotate in place; skips any leading 1 digits (k-axis)
   555
   556      int foundFirstNonZeroDigit = 0;
   557      for (int r = 1, res = H3_GET_RESOLUTION(h); r <= res; r++) {
   558          // rotate this digit
   559          H3_SET_INDEX_DIGIT(h, r, _rotate60ccw(H3_GET_INDEX_DIGIT(h, r)));
   560
   561          // look for the first non-zero digit so we
   562          // can adjust for deleted k-axes sequence
   563          // if necessary
   564          if (!foundFirstNonZeroDigit && H3_GET_INDEX_DIGIT(h, r) != 0) {
   565              foundFirstNonZeroDigit = 1;
   566
   567              // adjust for deleted k-axes sequence
   568              if (_h3LeadingNonZeroDigit(h) == K_AXES_DIGIT)
   569                  h = _h3Rotate60ccw(h);
   570          }
   571      }
   572      return h;
   573  }
