   600  /**
   601   * Rotate an H3Index 60 degrees counter-clockwise.
   602   * @param h The H3Index.
   603   */
   604  H3Index _h3Rotate60ccw(H3Index h) {
   605      for (int r = 1, res = H3_GET_RESOLUTION(h); r <= res; r++) {
   606          Direction oldDigit = H3_GET_INDEX_DIGIT(h, r);
   607          H3_SET_INDEX_DIGIT(h, r, _rotate60ccw(oldDigit));
   608      }
   609
   610      return h;
   611  }
